mapper.select:
SELECT id
FROM work_cases
WHERE status = 'ACCEPTED'
  AND starts_at <= #{readyAt}
  AND starts_at > #{noShowAfter}
  AND ends_at > #{endsAfter}
ORDER BY starts_at, id
LIMIT #{batchSize}

SELECT wc.id
FROM work_cases wc
WHERE wc.status = 'READY'
  AND (
      wc.starts_at <= #{noShowStartsAt}
      OR wc.ends_at <= #{noShowEndsAt}
  )
  AND NOT EXISTS (
      SELECT 1
      FROM attendance_records ar
      WHERE ar.work_case_id = wc.id
        AND ar.attendance_type = 'CHECK_IN'
        AND ar.result = 'SUCCESS'
  )
ORDER BY wc.starts_at, wc.id
LIMIT #{batchSize}

SELECT EXISTS(
    SELECT 1
    FROM attendance_records
    WHERE work_case_id = #{workCaseId}
      AND attendance_type = #{attendanceType}
      AND result = 'SUCCESS'
)
